var bgTex = _textures.Has("background") ? _textures.Get("background") : null;
if (bgTex != null && _spriteBatch != null)
{
    _spriteBatch.Begin(SpriteSortMode.Deferred, BlendState.Opaque);

    // ArcCreate: CameraService.cs:61-68 — AspectAdjustment
    var vp = GraphicsDevice.Viewport;
    float aspectAdj = (vp.Height / (vp.Width / 16f) - 9f) / 3f;
    // ArcCreate: CameraService.cs:243-248 — background pivot
    float pivotY = MathHelper.Lerp(0.87f, 0.5f, aspectAdj);
    // ArcCreate: Gameplay.unity CanvasScaler refRes=(2048,1536), match width=0
    float canvasScale = vp.Width / 2048f;
    float displayH = 1536f * canvasScale;
    // Crop: pivot anchored to screen top, image taller than screen
    float cropTop = displayH * (1f - pivotY);
    int srcY = (int)(cropTop / displayH * bgTex.Height);
    int srcH = (int)((float)vp.Height / displayH * bgTex.Height);
    srcH = Math.Min(srcH, bgTex.Height - srcY);

    _spriteBatch.Draw(bgTex,
        new Rectangle(0, 0, vp.Width, vp.Height),
        new Rectangle(0, srcY, bgTex.Width, srcH),
